import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Two distinct, real, infinite geometric series each have a sum of {sum_target} and share the same second term. The third term of one of the series is exactly {sum_target}/8. The common second term of both series can be written in the form (sqrt(m)-n)/p, where m, n, and p are positive integers and m is not divisible by the square of any prime. Find 100m+10n+p.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We choose sum_target so that the final common second term X = S*(sqrt(5)-1)/8
# can be written as (sqrt(m)-n)/p with m squarefree and p integer.
# Ensuring p integer requires S | 8, so pick S from {2,4,8} (exclude 1 to avoid trivial seed case).
S = rng.choice([2, 4, 8])
return {'sum_target': S}

    def verifier(assign):
# Verify structure and compute the required 100m+10n+p.
# We implement the derivation:
# Let S = sum_target. If the two distinct geometric series share the same second term X
# and one series has third term c = S/8, then from the sum constraint a = S(1-r),
# second term X = a r = S r(1-r), and third term c = a r^2 = S r^2(1-r) = r X.
# Eliminating r gives X^3 - S c X + S c^2 = 0. With c = S/8, this becomes
# X^3 - (S^2/8) X + (S^3/64) = 0. Scaling Y = X/S yields Y^3 - (1/8)Y + (1/64) = 0,
# which factors as (Y - 1/4)(Y^2 + (1/4)Y - (1/16)) = 0.
# The rational root Y=1/4 corresponds to r=1/2 and a unique series (degenerate),
# so the common X must be the other root Y = (sqrt(5)-1)/8 to yield two distinct ratios.
# Thus X = S * (sqrt(5)-1)/8.
# To express X in the required form (sqrt(m)-n)/p with m squarefree and integer p,
# we require p = 8/S to be integer; hence enforce S | 8.

# Domain checks
if 'sum_target' not in assign:
    # Missing assignment key
    return (False, None)
S = assign['sum_target']
if not isinstance(S, int):
    return (False, None)
if S <= 0:
    return (False, None)
if 8 % S != 0:
    # Enforce integrality of p and the intended radical form
    return (False, None)

# Compute the common second term X and verify the existence of two distinct valid ratios
sqrt5 = 5 ** 0.5
X = S * (sqrt5 - 1) / 8.0
# Discriminant for r from X = S r(1-r): r^2 - r + X/S = 0
disc = 1.0 - 4.0 * (X / S)
if disc <= 0:
    # Must have two distinct ratios to satisfy the 'distinct series' condition
    return (False, None)
r1 = (1.0 - disc ** 0.5) / 2.0
r2 = (1.0 + disc ** 0.5) / 2.0
# Check convergence |r|<1 and distinctness
if not (abs(r1) < 1.0 and abs(r2) < 1.0 and abs(r1 - r2) > 1e-12):
    return (False, None)
# Verify the series with third term c = S/8 exists and shares the same second term X.
c = S / 8.0
r_cand = c / X  # From c = r * X
if not (0.0 < r_cand < 1.0):
    return (False, None)
# Check that with this r_cand and S, the second term equals X within tolerance
X_check = S * r_cand * (1.0 - r_cand)
if abs(X_check - X) > 1e-12:
    return (False, None)

# Determine m, n, p for X written as (sqrt(m)-n)/p.
# Using X = S*(sqrt(5)-1)/8 = (sqrt(5) - 1) / (8/S) with p = 8/S, m = 5, n = 1.
p = 8 // S
m = 5
n = 1
# Final numeric answer
answer = 100 * m + 10 * n + p
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

